'use strict';
const REMEMBER_EMAIL='rotaryteck-remember-email';
function rememberedEmail(){try{return localStorage.getItem(REMEMBER_EMAIL)||'';}catch{return '';}}
function rememberEmail(value){try{if(value)localStorage.setItem(REMEMBER_EMAIL,value);else localStorage.removeItem(REMEMBER_EMAIL);}catch{}}
const AUTH_STORAGE='rotaryteck-manage-auth-v1';
let authConfig=null,authRefreshPromise=null;
function requestFetch(input,init={}){return fetch(input,{...init,signal:init.signal||AbortSignal.timeout(init.body instanceof FormData?60000:20000)});}

function authRead(){try{return JSON.parse(localStorage.getItem(AUTH_STORAGE)||'null');}catch{return null;}}
function authWrite(value){if(value){localStorage.setItem(AUTH_STORAGE,JSON.stringify(value));document.cookie='rt_access='+encodeURIComponent(value.access_token)+'; Path=/; Max-Age='+Math.max(60,Number(value.expires_in||3600))+'; Secure; SameSite=Strict';}else{localStorage.removeItem(AUTH_STORAGE);document.cookie='rt_access=; Path=/; Max-Age=0; Secure; SameSite=Strict';}}
function authExpired(session){if(!session?.access_token)return true;try{const payload=JSON.parse(atob(session.access_token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));return Number(payload.exp||0)*1000<Date.now()+60000;}catch{return true;}}
async function getAuthConfig(){if(authConfig)return authConfig;const r=await requestFetch('/api/auth/config',{cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||'登入服務尚未就緒');authConfig=data;return data;}
async function refreshAuth(){if(authRefreshPromise)return authRefreshPromise;authRefreshPromise=(async()=>{const current=authRead();if(!current?.refresh_token)return null;const cfg=await getAuthConfig(),r=await requestFetch(cfg.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:cfg.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:current.refresh_token})}),data=await r.json();if(!r.ok){authWrite(null);return null;}authWrite(data);return data;})();try{return await authRefreshPromise;}finally{authRefreshPromise=null;}}
async function authSession(){let session=authRead();if(authExpired(session))session=await refreshAuth();return session;}
async function apiFetch(input,init={}){const session=await authSession();if(!session){showLogin('登入已逾時，請重新登入。');throw Error('請先登入');}const headers=new Headers(init.headers||{});headers.set('Authorization','Bearer '+session.access_token);return requestFetch(input,{...init,headers});}
function loginField(label,type,name,extra=''){return `<label class="field">${label}<input type="${type}" name="${name}" ${extra}></label>`;}
function pendingEmailAction(){const params=new URLSearchParams(location.search);if(params.get('invited')==='1')return'invite';if(params.get('recovery')==='1')return'recovery';return null;}
function emailActionSession(){const params=new URLSearchParams(location.hash.replace(/^#/,'')),type=params.get('type');if(!['invite','recovery'].includes(type)||!params.get('access_token'))return null;const session={access_token:params.get('access_token'),refresh_token:params.get('refresh_token'),expires_in:Number(params.get('expires_in')||3600),token_type:params.get('token_type')||'bearer'};authWrite(session);history.replaceState(null,'',location.pathname+(type==='invite'?'?invited=1':'?recovery=1'));return{session,type};}
function showSetPassword(session,type='invite'){$('#cloud-status')?.remove();const recovery=type==='recovery';$('#app').innerHTML=`<main class="login-page"><section class="login-card"><div class="brand"><img class="login-logo" src="/api/login-logo" alt="公司 LOGO" onerror="this.onerror=null;this.src='favicon.svg'"><span>Rotaryteck Manage</span></div><h1>${recovery?'重設密碼':'設定登入密碼'}</h1><p>${recovery?'請設定新的登入密碼。':'請自行設定第一次登入密碼。'}</p><form id="set-password-form">${loginField('新密碼','password','password','autocomplete="new-password" minlength="8" required')}${loginField('再次輸入','password','confirm','autocomplete="new-password" minlength="8" required')}<small>至少 8 碼，包含英文字母與數字。</small><button class="primary" type="submit">${recovery?'更新密碼':'儲存並登入'}</button><p id="login-error" class="error" role="alert"></p></form></section></main>`;$('#set-password-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),button=e.submitter,box=$('#login-error'),password=String(fd.get('password')||''),confirmPassword=String(fd.get('confirm')||'');box.textContent='';if(password!==confirmPassword){box.textContent='兩次輸入的密碼不同。';return;}if(password.length<8||!/[A-Za-z]/.test(password)||!/\d/.test(password)){box.textContent='密碼至少 8 碼，需包含英文字母與數字。';return;}button.disabled=true;try{const current=await authSession();if(!current)throw Error('登入已逾時，請使用忘記密碼重新取得連結。');const cfg=await getAuthConfig(),r=await requestFetch(cfg.url+'/auth/v1/user',{method:'PUT',headers:{apikey:cfg.publishableKey,Authorization:'Bearer '+current.access_token,'Content-Type':'application/json'},body:JSON.stringify({password})}),data=await r.json();if(!r.ok)throw Error(data.message||data.msg||'密碼設定失敗');location.replace(location.origin+location.pathname);}catch(err){box.textContent=err.message||'密碼設定失敗，請重新開啟郵件連結。';button.disabled=false;}};}
function showForgotPassword(){$('#app').innerHTML=`<main class="login-page"><section class="login-card"><div class="brand"><img class="login-logo" src="/api/login-logo" alt="公司 LOGO" onerror="this.onerror=null;this.src='favicon.svg'"><span>Rotaryteck Manage</span></div><h1>忘記密碼</h1><p>輸入登入信箱，我們會寄出重設連結。</p><form id="forgot-password-form">${loginField('登入信箱','email','email','autocomplete="username" required')}<button class="primary" type="submit">寄送重設信</button><button class="login-link" id="back-to-login" type="button">返回登入</button><p id="login-error" class="error" role="alert"></p></form></section></main>`;$('#back-to-login').onclick=()=>showLogin();$('#forgot-password-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),button=e.submitter,box=$('#login-error');button.disabled=true;box.classList.remove('login-success');box.textContent='';try{const cfg=await getAuthConfig(),redirectTo=location.origin+location.pathname,r=await requestFetch(cfg.url+'/auth/v1/recover?redirect_to='+encodeURIComponent(redirectTo),{method:'POST',headers:{apikey:cfg.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({email:String(fd.get('email')||'').trim()})});if(!r.ok){const data=await r.json().catch(()=>({}));throw Error(data.message||data.msg||'重設信寄送失敗');}box.classList.add('login-success');box.textContent='如果此信箱已建立帳號，重設信將會寄出。請查看收件匣與垃圾郵件。';form.querySelector('input').disabled=true;}catch(err){box.textContent=err.message||'重設信寄送失敗，請稍後重試。';button.disabled=false;}};}
function showLogin(message=''){if(typeof activeConfirmation==='function')activeConfirmation();document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('#cloud-status')?.remove();$('#app').innerHTML=`<main class="login-page"><section class="login-card"><div class="brand"><img class="login-logo" src="/api/login-logo" alt="公司 LOGO" onerror="this.onerror=null;this.src='favicon.svg'"><span>Rotaryteck Manage</span></div><h1>登入管理系統</h1><p>使用主管建立的員工帳號登入。</p><form id="login-form">${loginField('登入信箱','email','email','autocomplete="username" required')}${loginField('密碼','password','password','autocomplete="current-password" minlength="8" required')}<button type="button" id="toggle-login-password" aria-pressed="false">顯示密碼</button><label class="remember-account"><input type="checkbox" id="remember-account" name="remember">記住帳號</label><button class="primary" type="submit">登入</button><button class="login-link" id="forgot-password" type="button">忘記密碼</button><p id="login-error" class="error" role="alert">${esc(message)}</p></form></section></main>`;const remembered=rememberedEmail();$('#login-form [name=email]').value=remembered;$('#remember-account').checked=!!remembered;$('#remember-account').onchange=e=>{if(!e.target.checked)rememberEmail('');};$('#toggle-login-password').onclick=e=>{const input=$('#login-form [name=password]'),show=input.type==='password';input.type=show?'text':'password';e.currentTarget.textContent=show?'隱藏密碼':'顯示密碼';e.currentTarget.setAttribute('aria-pressed',String(show));};$('#forgot-password').onclick=showForgotPassword;$('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,fd=new FormData(form),button=e.submitter,box=$('#login-error');button.disabled=true;box.textContent='';try{const cfg=await getAuthConfig(),r=await requestFetch(cfg.url+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:cfg.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({email:String(fd.get('email')||'').trim(),password:String(fd.get('password')||'')})}),data=await r.json();if(!r.ok){const reason=data.error_description||data.msg||data.message||data.error||'登入服務沒有提供原因';throw Error(`登入失敗：${reason}`);}rememberEmail(fd.get('remember')?String(fd.get('email')||'').trim():'');authWrite(data);location.reload();}catch(err){box.textContent=err.message||'登入失敗，請稍後重試。';button.disabled=false;}};}
async function ensureAuth(){try{const action=emailActionSession();if(action){showSetPassword(action.session,action.type);return false;}const pending=pendingEmailAction(),session=await authSession();if(!session){if(pending)history.replaceState(null,'',location.pathname);showLogin(pending?'設定連結已逾時，請重新寄送邀請或重設密碼信。':'');return false;}if(pending){showSetPassword(session,pending);return false;}return true;}catch(e){showLogin(e.message);return false;}}
function logout(){authWrite(null);history.replaceState(null,'',location.pathname);showLogin('已安全登出。');}
